-- EduNext MBA Admissions Hub 2027: tables + seed of the 333 reserved partner URLs (slugs match lib/mbaPartners.json).
-- Run once in Supabase SQL editor (project tnlbukkknbujenxjjmym).

create table if not exists public.mba_forms (
  slug text primary key,
  school text not null,
  microsite_id bigint references public.college_microsites(id) on delete set null,
  city text, region text,
  exams text,                       -- e.g. 'CAT, XAT, CMAT'
  programme text default 'PGDM / MBA 2027-29',
  form_url text,                    -- official application portal
  last_date date,
  fee_text text,
  status text not null default 'reserved' check (status in ('reserved','draft','live','featured','paused')),
  featured_until date,
  partner_contact text,
  updated_at timestamptz default now()
);

create table if not exists public.mba_form_clicks (
  id bigserial primary key,
  slug text references public.mba_forms(slug) on delete cascade,
  clicked_at timestamptz default now(),
  referrer text,
  user_id uuid
);

create table if not exists public.mba_form_alerts (   -- deadline reminders opt-in
  id bigserial primary key,
  slug text references public.mba_forms(slug) on delete cascade,
  name text, email text, phone text,
  created_at timestamptz default now()
);

alter table public.mba_forms enable row level security;
alter table public.mba_form_clicks enable row level security;
alter table public.mba_form_alerts enable row level security;
create policy "public read mba_forms" on public.mba_forms for select using (true);
create policy "public insert clicks" on public.mba_form_clicks for insert with check (true);
create policy "public insert alerts" on public.mba_form_alerts for insert with check (true);

on conflict (slug) do nothing;
